const bootSequence = [
  ["Initializing CRM...", "CRM Başlatılıyor..."],
  ["Initializing Yapay Zekâ Stüdyosu...", "Yapay Zekâ Stüdyosu Başlatılıyor..."],
  ["Initializing Reports...", "Raporlar Başlatılıyor..."],
  ["Initializing Discovery...", "İşletme Keşfi Başlatılıyor..."],
  ["Initializing Maps...", "Haritalar Başlatılıyor..."],
  ["Initializing Proposals...", "Teklif Motoru Başlatılıyor..."],
  ["Initializing Customers...", "Müşteriler Başlatılıyor..."],
  ["Initializing Operations...", "Operasyonlar Başlatılıyor..."]
];

function ToastStack({ items, dismiss }: any) {
  return <div className="hk-toast-stack" role="status" aria-live="polite">
    {items.map((toast) => {
      const icon = toast.type === "error" ? "❌" : toast.type === "warning" ? "⚠️" : toast.type === "info" ? "ℹ️" : "✅";
      const label = toast.type === "error" ? "İşlem başarısız" : toast.type === "warning" ? "Dikkat" : toast.type === "info" ? "Bilgi" : "İşlem başarılı";
      const tone = toast.type === "error" ? "hk-toast-error" : toast.type === "warning" ? "hk-toast-warning" : toast.type === "info" ? "hk-toast-info" : "hk-toast-success";
      return <button key={toast.id} type="button" onClick={() => dismiss(toast.id)} className={`hk-toast ${tone} grid grid-cols-[34px_1fr] items-start gap-3 p-4 text-left`}>
        <span className="hk-toast-icon grid size-8 place-items-center rounded-full text-base font-black">{icon}</span>
        <span><strong className="block text-xs font-black uppercase tracking-[.08em] text-slate-500">{label}</strong><span className="mt-1 block text-sm font-bold text-slate-950">{toast.message}</span><span className="mt-1 block text-xs text-slate-500">Kapatmak için tıklayın.</span></span>
      </button>;
    })}
  </div>;
}

function SystemBoot({ step }: { step: number }) {
  const complete = step >= bootSequence.length;
  return <div className="fixed inset-0 z-[100] grid place-items-center bg-white/70 px-5 ">
    <div className="w-full max-w-xl overflow-hidden rounded-[8px] border border-cyan-200/20 bg-white p-6 shadow-[0_28px_120px_rgba(34,211,238,.2)] sm:p-8">
      <div className="flex items-center justify-between gap-4"><div><p className="text-xs font-black uppercase tracking-[.2em] text-cyan-700">HK Operating System</p><p className="mt-2 text-[11px] font-bold uppercase tracking-[.18em] text-slate-500">Powered by HK Dijital</p></div><span className="grid size-11 place-items-center rounded-[8px] border border-cyan-200/20 bg-cyan-200/10 text-cyan-700"><Sparkles size={20} /></span></div>
      <div className="mt-7 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-cyan-300 transition-all duration-300" style={{ width: `${Math.min(100, step / bootSequence.length * 100)}%` }} /></div>
      <div className="mt-6 min-h-20">
        {complete ? <div className="animate-pulse"><p className="text-xl font-black text-slate-900">Welcome to HK OS</p><p className="mt-2 text-sm text-cyan-700">HK Operating System hazır.</p></div> : <><p className="text-lg font-black text-slate-900">{bootSequence[step]?.[0]}</p><p className="mt-2 text-sm text-cyan-700">{bootSequence[step]?.[1]}</p></>}
      </div>
      <p className="text-xs text-slate-500">Dijital Pazarlama Kontrol Merkezi</p>
    </div>
  </div>;
}

function Panel({ title, children }: any) {
  return <div className="w-full min-w-0 max-w-none"><p className="text-[10px] font-black uppercase tracking-[.2em] text-cyan-700">HK Operating System</p><h2 className="mb-6 mt-2 text-2xl font-black">{title}</h2>{children}</div>;
}

function Field({ label, value, onChange, type = "text", placeholder = "" }: any) {
  return <label className="grid gap-2 text-sm font-semibold text-slate-700">{label}<input type={type} value={value ?? ""} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className="min-h-11 rounded-[8px] border border-slate-200 bg-slate-50 px-3 text-slate-900 placeholder:text-slate-500" /></label>;
}

function TextArea({ label, value, onChange, rows = 4 }: any) {
  return <label className="grid gap-2 text-sm font-semibold text-slate-700">{label}<textarea rows={rows} value={value ?? ""} onChange={(e) => onChange(e.target.value)} className="rounded-[8px] border border-slate-200 bg-slate-50 px-3 py-3 text-slate-900" /></label>;
}

function SelectField({ label, value, onChange, options, placeholder = "Seçin" }: any) {
  return (
    <label className="grid gap-2 text-sm font-semibold text-slate-700">
      {label}
      <select value={value ?? ""} onChange={(e) => onChange(e.target.value)} className="min-h-11 rounded-[8px] border border-slate-200 bg-slate-50 px-3 text-slate-900">
        <option value="">{placeholder}</option>
        {options.map((option) => typeof option === "string" ? <option key={option} value={option}>{option}</option> : <option key={option.value} value={option.value}>{option.label}</option>)}
      </select>
    </label>
  );
}

function OtherSelectField({ label, value, onChange, options, manualLabel }: any) {
  const isKnown = options.includes(value);
  const selected = value && !isKnown ? "Diğer" : value || "";
  return (
    <div className="grid gap-3">
      <SelectField label={label} value={selected} onChange={(next) => onChange(next === "Diğer" ? "__other__" : next)} options={options} />
      {selected === "Diğer" && <Field label={manualLabel} value={value === "__other__" || isKnown ? "" : value} onChange={onChange} />}
    </div>
  );
}

function CompanySelect({ label = "Firma", value, onChange, companies }: any) {
  const selectableCompanies = useMemo(() => filterSelectableCustomers(companies), [companies]);
  return (
    <SelectField
      label={label}
      value={value}
      onChange={onChange}
      options={selectableCompanies.map((company) => ({ value: company.id, label: company.name }))}
      placeholder="Firma seçin"
    />
  );
}

function BranchAccessEditor({ user, setUser, branches }: any) {
  const companyBranches = (branches || []).filter((branch) => branch.company_id === user.company_id && branch.is_active !== false && !["passive", "pasif", "inactive"].includes(String(branch.status || "active").toLocaleLowerCase("tr")));
  const mode = user.branch_access_mode === "all" ? "all" : "selected";
  const selectedIds = Array.isArray(user.branch_ids) ? user.branch_ids : [];
  function setMode(nextMode: string) {
    setUser({ ...user, branch_access_mode: nextMode, branch_ids: nextMode === "all" ? [] : selectedIds, default_branch_id: companyBranches.some((branch) => branch.id === user.default_branch_id) ? user.default_branch_id : companyBranches[0]?.id || "" });
  }
  function toggleBranch(branchId: string) {
    const nextIds = selectedIds.includes(branchId) ? selectedIds.filter((id) => id !== branchId) : [...selectedIds, branchId];
    const defaultBranchId = nextIds.includes(user.default_branch_id) ? user.default_branch_id : nextIds[0] || "";
    setUser({ ...user, branch_ids: nextIds, default_branch_id: defaultBranchId });
  }
  if (!user.company_id) {
    return <div className="md:col-span-2 rounded-[14px] border border-dashed border-slate-300 bg-slate-50 p-4 text-sm text-slate-500">Şube erişimini düzenlemek için önce firma seçin.</div>;
  }
  return (
    <section className="min-w-0 rounded-[16px] border border-cyan-200 bg-cyan-50 p-4 md:col-span-2">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div><p className="text-xs font-black uppercase tracking-[.14em] text-cyan-700">Firma ve şube erişimi</p><p className="mt-1 text-sm text-cyan-950">Kullanıcının görebileceği şubeleri ve ilk açılacak şubeyi belirleyin.</p></div>
        <span className="rounded-full bg-white px-3 py-1 text-xs font-black text-cyan-800 ring-1 ring-cyan-200">{mode === "all" ? "Tüm şubeler" : `${selectedIds.length} şube seçili`}</span>
      </div>
      <div className="mt-4 grid gap-3 sm:grid-cols-2">
        {[{ value: "selected", label: "Seçili şubeler", note: "Yalnızca işaretlenen şubeler" }, { value: "all", label: "Tüm şubeler", note: "Mevcut ve gelecekteki tüm aktif şubeler" }].map((option) => <button type="button" key={option.value} onClick={() => setMode(option.value)} className={`rounded-[12px] border p-3 text-left ${mode === option.value ? "border-cyan-400 bg-white ring-2 ring-cyan-200" : "border-cyan-100 bg-cyan-50"}`}><strong className="block text-sm text-slate-950">{option.label}</strong><span className="mt-1 block text-xs text-slate-600">{option.note}</span></button>)}
      </div>
      {!companyBranches.length ? <p className="mt-4 rounded-[12px] border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800">Bu firmaya ait aktif şube bulunamadı. Önce firma profiline şube ekleyin.</p> : <>
        {mode === "selected" && <div className="mt-4"><div className="mb-2 flex flex-wrap gap-2"><button type="button" onClick={() => setUser({ ...user, branch_ids: companyBranches.map((branch) => branch.id), default_branch_id: user.default_branch_id || companyBranches[0]?.id || "" })} className="rounded-full border border-cyan-200 bg-white px-3 py-2 text-xs font-black text-cyan-800">Tümünü seç</button><button type="button" onClick={() => setUser({ ...user, branch_ids: [], default_branch_id: "" })} className="rounded-full border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-700">Seçimi temizle</button></div><div className="grid min-w-0 gap-2 sm:grid-cols-2 xl:grid-cols-3">{companyBranches.map((branch) => <label key={branch.id} className="flex min-w-0 items-start gap-3 rounded-[12px] border border-cyan-100 bg-white p-3 text-sm"><input type="checkbox" checked={selectedIds.includes(branch.id)} onChange={() => toggleBranch(branch.id)} className="mt-1 size-4 shrink-0" /><span className="min-w-0"><strong className="block break-words text-slate-950">{branch.branch_name}</strong><span className="mt-1 block break-words text-xs text-slate-500">{[branch.district, branch.city].filter(Boolean).join(" / ") || "Konum bilgisi yok"}</span></span></label>)}</div></div>}
        <label className="mt-4 grid gap-2 text-sm font-bold text-slate-700">Varsayılan şube<select value={user.default_branch_id || ""} onChange={(event) => setUser({ ...user, default_branch_id: event.target.value })} className="min-h-11 w-full min-w-0 rounded-[10px] border border-cyan-200 bg-white px-3 text-slate-900"><option value="">Varsayılan şube seçin</option>{companyBranches.filter((branch) => mode === "all" || selectedIds.includes(branch.id)).map((branch) => <option key={branch.id} value={branch.id}>{branch.branch_name}</option>)}</select></label>
        <p className="mt-3 text-xs leading-5 text-cyan-900">{mode === "all" ? "Bu kullanıcı mevcut ve gelecekte eklenecek tüm aktif şubelere erişebilir." : `${selectedIds.length} şubeye erişim verilecek.`}</p>
      </>}
    </section>
  );
}

function buildAdminNotifications(content: any, startupApiData: any = {}) {
  const today = new Date().toISOString().slice(0, 10);
  const weekEnd = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const companies = content.companies || [];
  const companyName = (companyId?: string) => companies.find((company) => company.id === companyId)?.name || "Müşteri yok";
  const payments = (content.paymentRecords || []).filter((item) => !item.archived_at && !item.deleted_at);
  const tasks = (content.agencyTasks || []).filter((item) => !item.archived_at && !item.deleted_at);
  const campaigns = (content.campaigns || []).filter((item) => !item.archived_at && !item.deleted_at && item.status !== "Arşivlendi");
  const leads = content.leads || [];
  const competitorSignals = (content.competitorSignals || []).filter((item) => !item.resolved_at).slice(0, 8);
  const agencyNotifications = (content.agencyNotifications || []).filter((item) => !item.archived_at && !item.is_read).slice(0, 8);
  const overduePayments = payments.filter((item) => item.status === "Gecikmiş" || (item.due_date && item.due_date < today && !["Ödendi", "İptal"].includes(item.status)));
  const todayTasks = tasks.filter((item) => item.due_date === today && !["Tamamlandı", "İptal"].includes(item.status));
  const criticalTasks = tasks.filter((item) => item.priority === "Kritik" && !["Tamamlandı", "İptal"].includes(item.status));
  const endingCampaigns = campaigns.filter((item) => item.end_date && item.end_date >= today && item.end_date <= weekEnd && !["Tamamlandı", "İptal"].includes(item.status));
  const newRequests = leads.filter((lead) => ["Yeni", "Yeni Başvuru"].includes(lead.status || "Yeni"));
  const followUpLeads = leads.filter((lead) => (lead.follow_up_date || lead.next_action_at) && String(lead.follow_up_date || lead.next_action_at).slice(0, 10) <= today && !["Kazanıldı", "Kaybedildi", "Dönüştürüldü", "Reddedildi"].includes(lead.status));
  const proposalFollowUps = leads.filter((lead) => pipelineStageForLead(lead) === "Teklif Gönderildi" && !["Kazanıldı", "Kaybedildi"].includes(lead.status));
  const latestLead = newRequests[0];
  const notifications = [
    followUpLeads.length && {
      id: `lead-follow-up-${followUpLeads.length}-${followUpLeads[0]?.id || "lead"}`,
      label: "Takip bekleyen leadler",
      text: `${followUpLeads.length} lead için takip zamanı geldi. İlk kayıt: ${followUpLeads[0]?.company || followUpLeads[0]?.name || "Lead"}`,
      tone: "amber",
      target: "Takip Merkezi"
    },
    proposalFollowUps.length && {
      id: `proposal-follow-up-${proposalFollowUps.length}-${proposalFollowUps[0]?.id || "proposal"}`,
      label: "Teklif takibi bekliyor",
      text: `${proposalFollowUps.length} teklif gönderilmiş lead takip bekliyor. İlk kayıt: ${proposalFollowUps[0]?.company || proposalFollowUps[0]?.name || "Teklif"}`,
      tone: "purple",
      target: "Takip Merkezi"
    },
    overduePayments.length && {
      id: `overdue-payments-${overduePayments.map((item) => item.id || item.due_date).join("-")}`,
      label: "Geciken tahsilatlar",
      text: `${overduePayments.length} tahsilat gecikmiş görünüyor. İlk kayıt: ${companyName(overduePayments[0]?.company_id)} · ${Number(overduePayments[0]?.amount || 0).toLocaleString("tr-TR")} TL`,
      tone: "amber",
      target: "Tahsilat"
    },
    todayTasks.length && {
      id: `today-tasks-${today}-${todayTasks.length}`,
      label: "Bugünkü görevler",
      text: `${todayTasks.length} görev bugün tamamlanmalı. Öncelikli kayıt: ${todayTasks[0]?.title || "Görev"}`,
      tone: "cyan",
      target: "Görevler"
    },
    criticalTasks.length && {
      id: `critical-tasks-${criticalTasks.map((item) => item.id || item.title).join("-")}`,
      label: "Kritik görevler",
      text: `${criticalTasks.length} kritik görev açık. İlk kayıt: ${criticalTasks[0]?.title || "Kritik görev"}`,
      tone: "purple",
      target: "Görevler"
    },
    endingCampaigns.length && {
      id: `ending-campaigns-${endingCampaigns.map((item) => item.id || item.name).join("-")}`,
      label: "Yaklaşan kampanya bitişleri",
      text: `${endingCampaigns.length} kampanya 7 gün içinde bitiyor. İlk kayıt: ${endingCampaigns[0]?.name || "Kampanya"} · ${companyName(endingCampaigns[0]?.company_id)}`,
      tone: "emerald",
      target: "Kampanyalar"
    },
    newRequests.length && {
      id: `new-requests-${newRequests.length}-${latestLead?.id || "lead"}`,
      label: "Yeni müşteri talepleri",
      text: `${newRequests.length} yeni talep takip bekliyor. Son kayıt: ${latestLead?.company || latestLead?.name || "Yeni başvuru"}`,
      tone: "cyan",
      target: "Leadler"
    },
    ...agencyNotifications.map((item) => ({
      id: `agency-notification-${item.id || item.title}`,
      label: item.title || "Ajans bildirimi",
      text: item.message || "Bildirim detayı bekleniyor.",
      tone: item.priority === "critical" || item.priority === "kritik" ? "red" : item.priority === "high" || item.priority === "yüksek" ? "amber" : "cyan",
      target: item.action_url ? "" : "Bildirim Merkezi",
      href: item.action_url || "",
      source: item.source_module || "Bildirim Merkezi",
      priority: item.priority || "normal",
      companyId: item.company_id,
      branchId: item.branch_id,
      showToCustomer: Boolean(item.show_to_customer)
    })),
    ...competitorSignals.map((item) => ({
      id: `competitor-signal-${item.id || item.title}`,
      label: item.title || "Yeni rakip sinyali",
      text: `${companyName(item.company_id)} için ${item.summary || item.customer_visible_summary || "rakip hareketi tespit edildi."}`,
      tone: item.severity === "critical" || item.severity === "kritik" ? "red" : item.severity === "warning" || item.severity === "orta" ? "amber" : "purple",
      target: "Rakip Analizi",
      source: "Rakip İstihbarat Merkezi",
      priority: item.severity || "bilgi",
      companyId: item.company_id,
      showToCustomer: Boolean(item.show_to_customer)
    })),
    {
      id: `system-health-${startupApiData?.lastTestTime || "pending"}`,
      label: "Sistem sağlığı",
      text: startupApiData?.lastTestTime ? `Son bağlantı kontrolü: ${new Date(startupApiData.lastTestTime).toLocaleString("tr-TR")}` : "Bağlantı testi bekleniyor.",
      tone: startupApiData?.lastTestTime ? "emerald" : "amber",
      target: "Sistem Sağlığı"
    }
  ].filter(Boolean);
  return notifications;
}

function GlobalCopilotPanel({ content, setActive, onClose, notify }: any) {
  const [prompt, setPrompt] = useState("Bugün neye odaklanmalıyım?");
  const [answer, setAnswer] = useState("");
  const [loading, setLoading] = useState(false);
  const prompts = [
    "Bu ay hangi müşterilere teklif vermeliyim?",
    "Performansı düşen müşteriler kim?",
    "Bu hafta hangi müşteriler aranmalı?",
    "Google puanı düşük müşteriler kim?",
    "Rakipleri reklam açan müşteriler kim?",
    "Tahsilat riski olan müşteriler kim?",
    "Eksik entegrasyonu olan müşteriler kim?",
    "Hangi müşteriye içerik planı hazırlamalıyım?"
  ];
  function localAnswer() {
    const tasks = content.agencyTasks || [];
    const payments = content.paymentRecords || [];
    const leads = content.leads || [];
    const campaigns = content.campaigns || [];
    const metrics = content.campaignMetrics || [];
    const competitorSignals = content.competitorSignals || [];
    const integrations = content.customerIntegrations || [];
    const overdue = payments.filter((item) => item.status === "Gecikmiş").slice(0, 6);
    const critical = tasks.filter((item) => item.priority === "Kritik" && item.status !== "Tamamlandı").slice(0, 6);
    const hot = leads.filter((lead) => Number(lead.lead_heat_score || 0) >= 70).slice(0, 6);
    const weakIntegrations = integrations.filter((item) => ["Eksik", "Kontrol gerekli", "Pasif", "Hata"].includes(item.status || item.sync_status || "")).slice(0, 6);
    const adSignals = competitorSignals.filter((item) => String(item.signal_type || item.title || "").toLocaleLowerCase("tr").includes("reklam")).slice(0, 6);
    const metaSpend = metrics.filter((item) => String(item.source || item.platform || "").toLocaleLowerCase("tr").includes("meta")).reduce((sum, item) => sum + Number(item.spend || item.spent || 0), 0);
    return [
      "HK Yapay Zekâ Ajans Asistanı yerel özet:",
      critical.length ? `Kritik görevler: ${critical.map((item) => item.title).join(", ")}` : "Kritik görev görünmüyor.",
      overdue.length ? `Geciken tahsilatlar: ${overdue.map((item) => `${companyName(content, item.company_id)} ${Number(item.amount || 0).toLocaleString("tr-TR")} TL`).join(", ")}` : "Geciken tahsilat görünmüyor.",
      hot.length ? `Takip edilecek sıcak leadler: ${hot.map((lead) => lead.company || lead.name).join(", ")}` : "Sıcak lead listesi sakin.",
      adSignals.length ? `Rakip reklam sinyali olan müşteriler: ${adSignals.map((item) => companyName(content, item.company_id)).join(", ")}` : "Açık rakip reklam sinyali görünmüyor.",
      weakIntegrations.length ? `Eksik entegrasyon sinyali: ${weakIntegrations.map((item) => companyName(content, item.company_id)).join(", ")}` : "Kritik entegrasyon eksiği görünmüyor.",
      `Aktif kampanya: ${campaigns.filter((item) => item.status === "Aktif").length}. Meta harcama: ${metaSpend.toLocaleString("tr-TR")} TL.`,
      "Öneri: Önce kritik görevleri kapatın, geciken tahsilatları arayın, rakip reklam sinyali olan müşteriler için kısa karşı hamle planı çıkarın."
    ].join("\n\n");
  }
  async function ask(question = prompt) {
    setPrompt(question);
    setLoading(true);
    const fallback = localAnswer();
    try {
      const response = await fetch("/api/admin/ai-generate", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt: `${question}\n\nAjans verisi: ${JSON.stringify({ tasks: (content.agencyTasks || []).slice(0, 20), payments: (content.paymentRecords || []).slice(0, 20), leads: (content.leads || []).slice(0, 20), campaigns: (content.campaigns || []).slice(0, 20), competitorSignals: (content.competitorSignals || []).slice(0, 20), integrations: (content.customerIntegrations || []).slice(0, 20) })}\n\nTürkçe, kısa ve uygulanabilir yanıt ver. Cevapta müşteri, görev, rakip analizi, rapor, teklif ve WhatsApp aksiyonlarını belirt.` }) });
      const data = await response.json().catch(() => ({}));
      setAnswer(response.ok && data.output ? data.output : fallback);
    } catch {
      setAnswer(fallback);
    } finally {
      setLoading(false);
      notify?.("HK Copilot yanıtı hazırlandı.", "success");
    }
  }
  const actionCards = [
    ["Müşteri profilini aç", "Müşteriler", "Öncelikli müşterinin 360 profilini kontrol et."],
    ["Görev oluştur", "Görevler", "Öneriyi operasyon görevine dönüştür."],
    ["Rakip analizine git", "Rakip Analizi", "Rakip sinyallerini ve müşteri özetini incele."],
    ["Rapor hazırla", "Müşteri Raporları", "Müşteriye gönderilecek raporu hazırla."],
    ["Teklif oluştur", "Teklif Oluştur", "Satış veya yenileme teklifi hazırla."],
    ["WhatsApp mesajı hazırla", "WhatsApp Hatırlatma", "Müşteri iletişim metnini hazırla."]
  ];
  return <div className="fixed inset-0 z-[85] flex justify-end bg-white/75" onMouseDown={onClose}><aside className="h-full w-full max-w-xl overflow-y-auto border-l border-slate-200 bg-white p-5 shadow-[0_24px_90px_rgba(15,23,42,.16)]" onMouseDown={(event) => event.stopPropagation()}><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-black uppercase tracking-[.16em] text-purple-600">HK Intelligence</p><h2 className="mt-1 text-2xl font-black text-slate-950">Yapay Zekâ Ajans Asistanı</h2><p className="mt-2 text-sm leading-6 text-slate-500">Müşteri, görev, tahsilat, rakip sinyali ve entegrasyon verilerinden aksiyon önerisi üretir. Yapay zekâ yoksa yerel kural tabanlı özet döner.</p></div><button onClick={onClose} className="grid size-10 place-items-center rounded-[12px] border border-slate-200 text-slate-600"><X size={18} /></button></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{prompts.map((item) => <button key={item} onClick={() => ask(item)} className="rounded-[14px] border border-slate-200 bg-slate-50 p-3 text-left text-xs font-black text-slate-700 hover:border-purple-200 hover:bg-purple-50">{item}</button>)}</div><div className="mt-5"><TextArea label="Asistan sorusu" value={prompt} onChange={setPrompt} /><div className="mt-3 flex flex-wrap gap-2"><button disabled={loading} onClick={() => ask(prompt)} className="rounded-full bg-purple-100 px-5 py-3 text-sm font-black text-purple-700 ring-1 ring-purple-200 disabled:opacity-60">{loading ? "Yanıt hazırlanıyor..." : "Sor"}</button><button onClick={() => { setActive("HK Asistan"); onClose(); }} className="rounded-full border border-slate-200 px-5 py-3 text-sm font-black text-slate-700">HK Asistan sayfasını aç</button></div></div>{answer && <><pre className="mt-5 whitespace-pre-wrap rounded-[16px] border border-purple-100 bg-purple-50 p-4 text-sm leading-7 text-slate-700">{answer}</pre><div className="mt-4 grid gap-2 sm:grid-cols-2">{actionCards.map(([label, target, detail]) => <button key={label} onClick={() => { setActive(target); onClose(); }} className="rounded-[14px] border border-slate-200 bg-white p-3 text-left hover:border-purple-200 hover:bg-purple-50"><strong className="block text-xs text-slate-950">{label}</strong><span className="mt-1 block text-[11px] leading-5 text-slate-500">{detail}</span></button>)}</div></>}</aside></div>;
}

function AdminBrowserControls() {
  const buttonClass = "admin-browser-control text-xs";
  return (
    <div className="admin-browser-controls">
      <button type="button" title="Geri" aria-label="Geri" onClick={() => window.history.back()} className={buttonClass}>
        <span aria-hidden="true">←</span><span className="hidden sm:inline">Geri</span>
      </button>
      <button type="button" title="İleri" aria-label="İleri" onClick={() => window.history.forward()} className={buttonClass}>
        <span className="hidden sm:inline">İleri</span><span aria-hidden="true">→</span>
      </button>
      <button type="button" title="Yenile" aria-label="Yenile" onClick={() => window.location.reload()} className={buttonClass}>
        Yenile
      </button>
    </div>
  );
}

function GlobalSearchPage() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  async function runSearch() {
    if (query.trim().length < 2) return setResults([]);
    setLoading(true);
    const response = await fetch(`/api/admin/search?q=${encodeURIComponent(query)}`);
    const data = await response.json().catch(() => ({}));
    setResults(response.ok ? data.results || [] : []);
    setLoading(false);
  }
  return <Panel title="Genel Arama"><p className="mb-4 text-sm leading-6 text-slate-400">Yetkiniz bulunan modüller, başvurular, müşteriler ve raporlar içinde arama yapın.</p><div className="flex gap-2"><input value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => event.key === "Enter" && runSearch()} placeholder="Aramak istediğiniz kelimeyi yazın..." className="min-h-12 flex-1 rounded-[8px] border border-slate-200 bg-slate-50 px-4 text-slate-900" /><button onClick={runSearch} className="rounded-[8px] bg-cyan-300 px-5 text-sm font-black text-slate-950">{loading ? "Aranıyor..." : "Ara"}</button></div><div className="mt-5 grid gap-3">{results.map((result) => <Link key={result.id} href={result.href} className="flex items-center justify-between gap-3 rounded-[8px] border border-slate-200 bg-slate-50 p-4 transition hover:border-cyan-200/40"><span><strong>{result.title}</strong><span className="mt-1 block text-sm text-slate-400">{result.detail}</span></span><span className="rounded-full border border-slate-200 px-3 py-1 text-xs text-cyan-700">{result.type}</span></Link>)}{query && !loading && !results.length && <p className="rounded-[8px] border border-dashed border-slate-200 p-6 text-center text-sm text-slate-400">Aramanızla eşleşen kayıt bulunamadı.</p>}</div></Panel>;
}

