          {form.rangePreset === "custom" && <Field label="Bitiş tarihi" type="date" value={form.dateTo} onChange={(dateTo) => setForm({ ...form, dateTo })} />}
          <InfoItem label="Son Meta senkronizasyon" value={formatDateTime(linked.last_sync_at)} />
